<?php $isStudent=$user['role']==='user'; ?>
<div class="welcome-row"><div><div class="eyebrow"><?= $isStudent?'PUSAT BANTUAN':'LAYANAN PENGGUNA' ?></div><h1><?= $isStudent?'Keluhan dan bantuan':'Keluhan siswa/mahasiswa' ?></h1><p class="muted"><?= $isStudent?'Sampaikan kendala dan pantau tindak lanjut admin institusi.':'Tinjau laporan pengguna dan kirim jawaban dari institusi.' ?></p></div></div>
<?php if($isStudent): ?><details class="panel resource-form"><summary>＋ Buat laporan keluhan</summary><form method="post" class="resource-fields"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_complaint"><label>Kategori<select name="category"><option value="peminjaman">Peminjaman</option><option value="fasilitas">Fasilitas</option><option value="akun">Akun</option><option value="layanan">Layanan</option><option value="lainnya">Lainnya</option></select></label><label>Transaksi terkait (opsional)<select name="borrowing_id"><option value="">Tidak terkait</option><?php foreach($my_borrowings as $borrowing): ?><option value="<?= (int)$borrowing['id'] ?>">Peminjaman #<?= (int)$borrowing['id'] ?></option><?php endforeach; ?></select></label><label>Subjek<input name="subject" maxlength="180" required></label><label class="field-wide">Jelaskan keluhan<textarea name="message" rows="4" minlength="10" required></textarea></label><div class="field-wide"><button class="btn btn-primary">Kirim keluhan</button></div></form></details><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h2><?= $isStudent?'Laporan saya':'Laporan masuk' ?></h2><p><?= count($complaints) ?> laporan</p></div></div>
<?php if(!$complaints): ?><div class="empty-state"><span>⚑</span><strong>Belum ada keluhan</strong><p>Laporan yang dikirim akan muncul di sini.</p></div><?php else: ?>
<div class="complaint-list"><?php foreach($complaints as $complaint): ?><article class="complaint-card"><div class="complaint-top"><div><span class="badge role-badge"><?= e(ucfirst($complaint['category'])) ?></span><h3><?= e($complaint['subject']) ?></h3><small><?= $isStudent?'Dikirim':'Dari '.e($complaint['reporter']).($complaint['student_number']?' · NIS/NIM '.e($complaint['student_number']):'') ?> · <?= e(date('d M Y H:i',strtotime($complaint['created_at']))) ?></small></div><span class="badge status-<?= e(['new'=>'waiting','in_progress'=>'borrowed','resolved'=>'completed','closed'=>'rejected'][$complaint['status']]??'waiting') ?>"><?= e(['new'=>'Baru','in_progress'=>'Diproses','resolved'=>'Selesai','closed'=>'Ditutup'][$complaint['status']]??$complaint['status']) ?></span></div><p><?= nl2br(e($complaint['message'])) ?></p><?php if($complaint['admin_reply']): ?><div class="complaint-reply"><strong>Jawaban admin</strong><p><?= nl2br(e($complaint['admin_reply'])) ?></p></div><?php endif; ?>
<?php if(!$isStudent): ?><form method="post" class="complaint-update"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_complaint"><input type="hidden" name="complaint_id" value="<?= (int)$complaint['id'] ?>"><select name="status"><option value="new" <?= $complaint['status']==='new'?'selected':'' ?>>Baru</option><option value="in_progress" <?= $complaint['status']==='in_progress'?'selected':'' ?>>Diproses</option><option value="resolved" <?= $complaint['status']==='resolved'?'selected':'' ?>>Selesai</option><option value="closed" <?= $complaint['status']==='closed'?'selected':'' ?>>Ditutup</option></select><input name="admin_reply" value="<?= e($complaint['admin_reply']??'') ?>" placeholder="Tulis jawaban kepada pelapor"><button class="btn btn-primary">Simpan tindak lanjut</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
</section>
